async def git_clone_repo(repo_url: str, target_folder: str) -> str:
    """Clone a git repository to a specified folder.

    Args:
        repo_url: URL of the git repository to clone
        target_folder: Path to the folder where the repository should be cloned
    """
    # Check if target folder exists
    target_path = Path(target_folder).expanduser().absolute()
    if target_path.exists():
        return json.dumps({
            "success": False,
            "error": f"Target folder already exists: {str(target_path)}"
        })

    # Check if git is installed
    try:
        subprocess.run(["git", "--version"], check=True, capture_output=True, text=True)
    except FileNotFoundError:
        return json.dumps({
            "success": False,
            "error": "Git is not installed. Please install Git first."
        })
    except subprocess.CalledProcessError:
        return json.dumps({
            "success": False,
            "error": "Error checking Git installation."
        })

    # Create parent directory if it doesn't exist
    target_path.parent.mkdir(parents=True, exist_ok=True)

    # Clone the repository
    try:
        result = subprocess.run(
            ["git", "clone", repo_url, str(target_path)],
            check=True,
            capture_output=True,
            text=True
        )
        return json.dumps({
            "success": True,
            "target_folder": str(target_path)
        })
    except subprocess.CalledProcessError as e:
        return json.dumps({
            "success": False,
            "error": f"Git clone failed: {e.stderr}"
        })

async def open_in_vscode(folder_path: str, use_insiders: bool = False) -> str:
    """Open a folder in VS Code or VS Code Insiders application.

    Args:
        folder_path: Path to the folder to open
        use_insiders: Whether to use VS Code Insiders instead of regular VS Code
    """
    folder_path = Path(folder_path).expanduser().absolute()

    if not folder_path.exists():
        return json.dumps({
            "success": False,
            "error": f"Folder does not exist: {str(folder_path)}"
        })

    # Determine the command based on OS and whether to use Insiders
    system = platform.system()

    try:
        if system == "Darwin":  # macOS
            app_name = "Visual Studio Code - Insiders" if use_insiders else "Visual Studio Code"
            subprocess.run(["open", "-a", app_name, str(folder_path)], check=True)
        elif system == "Windows":
            # On Windows, use the start command to open the application
            vscode_path = os.path.join(os.environ.get("LOCALAPPDATA", ""), 
                                      "Programs",
                                      "Microsoft VS Code Insiders" if use_insiders else "Microsoft VS Code",
                                      "Code.exe")

            # Check if VS Code exists at the expected path
            if not os.path.exists(vscode_path):
                # Try alternative installation paths
                program_files = os.environ.get("ProgramFiles", "C:\\Program Files")
                program_files_x86 = os.environ.get("ProgramFiles(x86)", "C:\\Program Files (x86)")

                alt_paths = [
                    os.path.join(program_files, "Microsoft VS Code" + (" Insiders" if use_insiders else ""), "Code.exe"),
                    os.path.join(program_files_x86, "Microsoft VS Code" + (" Insiders" if use_insiders else ""), "Code.exe")
                ]

                for path in alt_paths:
                    if os.path.exists(path):
                        vscode_path = path
                        break

            if os.path.exists(vscode_path):
                # Launch the resolved executable directly (no shell) to avoid
                # command injection via shell metacharacters in folder_path.
                subprocess.run([vscode_path, str(folder_path)], check=True)
            else:
                # Fallback to command line approach
                cmd = "code-insiders" if use_insiders else "code"
                subprocess.run([cmd, str(folder_path)], check=True)

        elif system == "Linux":
            # On Linux, try to use the desktop application
            app_name = "code-insiders" if use_insiders else "code"

            # Try using xdg-open which should use the desktop application
            try:
                subprocess.run(["xdg-open", str(folder_path)], check=True)
            except (FileNotFoundError, subprocess.CalledProcessError):
                # Fallback to direct command
                subprocess.run([app_name, str(folder_path)], check=True)
        else:
            return json.dumps({
                "success": False,
                "error": f"Unsupported operating system: {system}"
            })

        return json.dumps({
            "success": True,
            "message": f"Opened {str(folder_path)} in {'VS Code Insiders' if use_insiders else 'VS Code'}"
        })
    except subprocess.CalledProcessError as e:
        return json.dumps({
            "success": False,
            "error": f"Failed to open VS Code: {str(e)}"
        })
    except FileNotFoundError:
        return json.dumps({
            "success": False,
            "error": f"{'VS Code Insiders' if use_insiders else 'VS Code'} is not installed or not in PATH"
        })

def add(a: float, b: float) -> float:
    """Add two numbers together and return the result."""
    return a + b

def subtract(a: float, b: float) -> float:
    """Subtract b from a and return the result."""
    return a - b

def multiply(a: float, b: float) -> float:
    """Multiply two numbers together and return the result."""
    return a * b

async def list_todos(self) -> str:
        """List all of the user's todos with their id and done/not-done state."""

        todos = await user.load("todos", [])
        if not todos:
            return "The to-do list is empty."
        return "\n".join(
            f"[{'x' if t['done'] else ' '}] #{t['id']} {t['text']}"
            for t in todos
        )

def list_devices() -> dict:
    _ensure_connected()
    return {"devices": adb.devices()}

def open_app(app_name: str) -> dict:
    _ensure_connected()
    output = adb.open_app(app_name)
    return {"status": "ok", "app_name": app_name, "output": output}

def visit(url: str) -> dict:
    url = url.strip()
    if not url:
        raise ValueError("url must not be empty")
    if "://" not in url:
        url = f"https://{url}"

    _ensure_connected()
    output = adb.visit(url)
    return {"status": "ok", "url": url, "output": output}

def current_window() -> dict:
    _ensure_connected()
    return {"current_window": adb.current_window()}

def press_button(button:str) -> dict:
    _ensure_connected()
    output = adb.press_button(button)
    return {"status": "ok", "button": button, "output": output}

def wait(seconds: int) -> dict:
    _ensure_connected()
    if seconds < 0:
        raise ValueError("seconds must not be negative")
    time.sleep(seconds)
    return {"status": "ok", "waited_seconds": seconds}

def list_tool_groups() -> str:
    """
    List all available tool groups with their tool counts and loaded status.

    Returns each category with: tool count, loaded status, and tool names.
    Use load_tool_group(group) to load a group's tools.
    """
    if not state._full_schema:
        return json.dumps({"error": "No instance connected. Use connect_instance() first."})
    groups = registry._get_group_info()
    return json.dumps({"groups": groups, "total_tools": len(state._full_schema)}, indent=2)

async def load_tool_group(
    group: Annotated[str, Field(description='Category name (e.g. "function", "datatype") or "all"')],
    ctx: Context | None = None,
) -> str:
    """
    Load all tools in a category. Accepts a category name or "all" to load everything.

    Use list_tool_groups() to see available categories.

    Args:
        group: Category name (e.g. "function", "datatype") or "all"
    """
    if not state._full_schema:
        return json.dumps({"error": "No instance connected. Use connect_instance() first."})

    state.remember_tools_changed_context(ctx)

    def _notify_if_changed(result):
        if result:
            state.notify_tools_changed_from_worker()

    if group == "all":
        # Load all unloaded groups
        all_groups = {td.get("category", "unknown") for td in state._full_schema}
        all_loaded = await state.run_in_worker(
            _load_groups_sync,
            sorted(all_groups),
            done_callback=_notify_if_changed,
        )
        return json.dumps(
            {
                "loaded": "all",
                "new_tools": len(all_loaded),
                "new_tool_names": sorted(all_loaded),
                "total_loaded": len(state._dynamic_tool_names),
            }
        )

    loaded_names = await state.run_in_worker(
        registry._load_group,
        group,
        done_callback=_notify_if_changed,
    )
    if not loaded_names:
        available = sorted({td.get("category", "unknown") for td in state._full_schema})
        if group in state._loaded_groups:
            # Already loaded — return the tool names so the agent knows what's callable
            already = sorted(td["name"] for td in state._full_schema if td.get("category") == group)
            return json.dumps(
                {
                    "message": f"Group '{group}' is already loaded.",
                    "tools": already,
                    "loaded_groups": sorted(state._loaded_groups),
                }
            )
        return json.dumps(
            {
                "error": f"No tools found for group '{group}'",
                "available_groups": available,
            }
        )
    return json.dumps(
        {
            "loaded": group,
            "new_tools": len(loaded_names),
            "tools": sorted(loaded_names),
            "total_loaded": len(state._dynamic_tool_names),
            "loaded_groups": sorted(state._loaded_groups),
        }
    )

async def unload_tool_group(
    group: Annotated[str, Field(description="Category name to unload")],
    ctx: Context | None = None,
) -> str:
    """
    Unload all tools in a category. Default groups are protected from unloading.

    Args:
        group: Category name to unload
    """
    if group in state._default_groups:
        return json.dumps(
            {
                "error": f"Cannot unload default group '{group}'",
                "default_groups": sorted(state._default_groups),
            }
        )

    state.remember_tools_changed_context(ctx)

    removed = await state.run_in_worker(
        registry._unload_group,
        group,
        done_callback=lambda result: result > 0 and state.notify_tools_changed_from_worker(),
    )
    if removed == 0:
        return json.dumps({"message": f"Group '{group}' is not loaded or has no tools."})
    return json.dumps(
        {
            "unloaded": group,
            "removed_tools": removed,
            "total_loaded": len(state._dynamic_tool_names),
            "loaded_groups": sorted(state._loaded_groups),
        }
    )

async def check_tools(
    tools: Annotated[
        str,
        Field(
            description=(
                "Comma-separated tool names, e.g. "
                '"rename_symbol,batch_set_comments,analyze_function_completeness"'
            )
        ),
    ],
) -> str:
    """
    Check if specific tools are callable right now. Returns status for each tool:
    "callable", "not_loaded" (exists but group not loaded), or "not_found" (doesn't exist).

    Args:
        tools: Comma-separated tool names, e.g. "rename_symbol,batch_set_comments,analyze_function_completeness"
    """
    tool_names = [t.strip() for t in tools.split(",") if t.strip()]
    if not tool_names:
        return json.dumps({"error": "Provide comma-separated tool names"})

    # Build lookup of all known tools -> their group
    all_known: dict[str, str] = {}
    for td in state._full_schema:
        all_known[td["name"]] = td.get("category", "unknown")

    # With no schema fetched there is nothing to check a name against, and
    # every Ghidra tool would be reported "not_found" — indistinguishable from
    # a tool that genuinely doesn't exist. Say "unknown" and name the fix.
    schema_available = bool(all_known)

    # Check each tool
    results: dict[str, dict] = {}
    for name in tool_names:
        if name in STATIC_TOOL_NAMES:
            results[name] = {"status": "callable", "type": "static"}
        elif not schema_available:
            results[name] = {
                "status": "unknown",
                "reason": "no instance connected — tool schema not loaded",
                "fix": "connect_instance(project)",
            }
        elif name in state._dynamic_tool_names:
            results[name] = {
                "status": "callable",
                "group": all_known.get(name, "unknown"),
            }
        elif name in all_known:
            group = all_known[name]
            results[name] = {
                "status": "not_loaded",
                "group": group,
                "fix": f'load_tool_group("{group}")',
            }
        else:
            results[name] = {"status": "not_found"}

    callable_count = sum(1 for r in results.values() if r["status"] == "callable")
    return json.dumps(
        {
            "results": results,
            "summary": f"{callable_count}/{len(tool_names)} callable",
        }
    )

async def get_tripo_status(ctx: Context, user_prompt: str = "") -> str:
    """
    Check if Tripo 3D generation is enabled in Blender. Tripo is only available with
    MCP for Blender Premium; with the user's own API keys it reports as unavailable.
    With MCP for Blender Premium on, no API key is needed: the message says "Mode: PREMIUM", the
    plan's generations left, and which flow to follow.
    """
    try:
        blender = get_blender_connection()
        result = blender.send_command("get_tripo_status")
        return result.get("message", "") + premium_hint_once(ctx, result)
    except Exception as e:
        return _tripo_error("checking", e)

async def poll_tripo_job_status(ctx: Context, request_id: str):
    """
    Check if a Tripo generation is finished.

    Parameters:
    - request_id: The request_id given in the generate step.

    Returns the status: "IN_QUEUE", "IN_PROGRESS", "COMPLETED", or a failure. Generation takes a minute
    or two; poll until COMPLETED or a failed state, then call import_generated_asset_tripo.
    If the result has a `code` field, relay `message` to the user as written and do not retry automatically.
    """
    try:
        return get_blender_connection().send_command("poll_tripo_job_status", {"request_id": request_id})
    except Exception as e:
        return _tripo_error("polling", e)

async def import_generated_asset_tripo(ctx: Context, request_id: str, name: str):
    """
    Import a finished Tripo generation into the scene as one mesh object.

    Parameters:
    - request_id: The request_id given in the generate step.
    - name: The name of the object in scene.

    Afterwards ALWAYS check world_bounding_box and adjust the object's location, scale and rotation.
    """
    try:
        return get_blender_connection().send_command(
            "import_generated_asset_tripo", {"request_id": request_id, "name": name})
    except Exception as e:
        return _tripo_error("importing from", e)

def get_notes_tool(
    item_key: str | None = None,
    query: str | None = None,
    limit: int | str | None = 20,
    truncate: bool = True,
    raw_html: bool = False,
    *,
    ctx: Context
) -> str:
    """Dispatch the note-read surface to listing or full-text search."""
    if query is not None and query.strip():
        if item_key:
            return (
                "Error: query and item_key cannot be combined — note search "
                "is library-wide. Call with item_key alone to list one "
                "item's notes, or with query alone to search the library."
            )
        return search_notes(query=query, limit=limit, raw_html=raw_html, ctx=ctx)

    if query is not None:
        return "Error: Search query cannot be empty"

    return get_notes(
        item_key=item_key,
        limit=limit,
        truncate=truncate,
        raw_html=raw_html,
        ctx=ctx,
    )

def manage_note(
    action: Literal["create", "update", "delete"],
    item_key: str,
    note_text: str | None = None,
    note_title: str | None = None,
    tags: list[str] | str | None = None,
    append: bool = False,
    *,
    ctx: Context
) -> str:
    """Dispatch the note-write surface to create/update/delete."""
    if action == "create":
        if not note_text:
            return (
                "Error: action='create' requires note_text (the note body). "
                "item_key must be the parent item the note is attached to."
            )
        return create_note(
            item_key=item_key,
            note_title=note_title or "",
            note_text=note_text,
            tags=tags,
            ctx=ctx,
        )

    if action == "update":
        if note_text is None:
            return (
                "Error: action='update' requires note_text (the new HTML "
                "body). item_key must be the note's own key."
            )
        return update_note(
            item_key=item_key, note_text=note_text, append=append, ctx=ctx
        )

    if action == "delete":
        if note_text is not None:
            return (
                "Error: action='delete' takes only item_key (the note's own "
                "key); note_text is not applicable. Use action='update' to "
                "change a note's content."
            )
        return delete_note(item_key=item_key, ctx=ctx)

    return (
        f"Error: unknown action '{action}'. "
        "Expected one of: create, update, delete."
    )

def update_annotation(
    annotation_key: str,
    text: str | None = None,
    comment: str | None = None,
    color: str | None = None,
    tags: list[str] | str | None = None,
    add_tags: list[str] | str | None = None,
    remove_tags: list[str] | str | None = None,
    *,
    ctx: Context
) -> str:
    try:
        if tags is not None and (add_tags is not None or remove_tags is not None):
            return (
                "Error: Cannot use 'tags' (replace all) together with "
                "'add_tags'/'remove_tags' (incremental). Use one approach or the other."
            )

        ctx.info(f"Updating annotation {annotation_key}")

        zot, err = _get_note_write_client("updating annotations")
        if err:
            return err

        try:
            item = zot.item(annotation_key)
        except Exception:
            return f"Error: No item found with key: {annotation_key}"

        data = item.get("data", {})
        if data.get("itemType") != "annotation":
            return (
                f"Error: Item {annotation_key} is not an annotation "
                f"(itemType={data.get('itemType')})"
            )

        changes = []
        if text is not None:
            data["annotationText"] = text
            changes.append("- **text**: updated")
        if comment is not None:
            data["annotationComment"] = comment
            changes.append("- **comment**: updated")
        if color is not None:
            data["annotationColor"] = color
            changes.append(f"- **color**: {color}")

        if tags is not None:
            tag_list = _helpers._normalize_str_list_input(tags, "tags")
            data["tags"] = [{"tag": t} for t in tag_list]
            changes.append(f"- **tags**: replaced with {tag_list}")
        elif add_tags is not None or remove_tags is not None:
            existing = {t["tag"] for t in data.get("tags", [])}
            if add_tags is not None:
                to_add = _helpers._normalize_str_list_input(add_tags, "add_tags")
                existing.update(to_add)
                changes.append(f"- **tags**: added {to_add}")
            if remove_tags is not None:
                to_remove = set(
                    _helpers._normalize_str_list_input(remove_tags, "remove_tags")
                )
                existing -= to_remove
                changes.append(f"- **tags**: removed {list(to_remove)}")
            data["tags"] = [{"tag": t} for t in sorted(existing)]

        if not changes:
            return "No changes to apply."

        resp = zot.update_item(item)
        if _helpers._handle_write_response(resp, ctx):
            return (
                f"Successfully updated annotation `{annotation_key}`:\n\n"
                + "\n".join(changes)
            )
        return f"Failed to update annotation {annotation_key}"

    except ValueError as e:
        return f"Input error: {e}"
    except Exception as e:
        ctx.error(f"Error updating annotation: {e}")
        return f"Error updating annotation: {_helpers.format_zotero_error(e)}"

def delete_annotation(
    annotation_key: str,
    *,
    ctx: Context
) -> str:
    try:
        ctx.info(f"Deleting annotation {annotation_key}")

        zot, err = _get_note_write_client("deleting annotations")
        if err:
            return err

        try:
            item = zot.item(annotation_key)
        except Exception:
            return f"Error: No item found with key: {annotation_key}"

        data = item.get("data", {})
        if data.get("itemType") != "annotation":
            return (
                f"Error: Item {annotation_key} is not an annotation "
                f"(itemType={data.get('itemType')})"
            )

        # pyzotero raises on a refused write and returns True otherwise.
        zot.delete_item(item)
        return f"Successfully deleted annotation {annotation_key}"

    except Exception as e:
        ctx.error(f"Error deleting annotation: {str(e)}")
        return f"Error deleting annotation: {_helpers.format_zotero_error(e)}"

def chatgpt_connector_search(
    query: str,
    *,
    ctx: Context
) -> str:
    """
    Returns a JSON-encoded string with shape {"results": [{"id","title","url"}, ...]}.
    The MCP runtime wraps this string as a single text content item.
    """
    default_limit = 10
    # (key, title) pairs. Semantic first; a missing extra, an unbuilt index or
    # an empty answer all fall through to keyword search, so a core install
    # still gives the connector something to cite.
    hits: list[tuple[str, str]] = []
    try:
        from zotero_mcp.semantic_search import create_semantic_search

        config_path = Path.home() / ".config" / "zotero-mcp" / "config.json"
        search = create_semantic_search(str(config_path))
        results = search.search(query=query, limit=default_limit, filters=None) or {}
        for r in results.get("results", []):
            data = (r.get("zotero_item") or {}).get("data", {})
            hits.append((r.get("item_key") or "", data.get("title", "")))
    except Exception as e:
        ctx.info(f"Semantic search unavailable, using keyword search: {e}")
    if not hits:
        try:
            items = _library.get_library_backend().search_items(
                query, qmode="everything", limit=default_limit
            )
            hits = [(i.get("key", ""), i.get("data", {}).get("title", "")) for i in items]
        except Exception as e:
            ctx.error(f"Error in search wrapper: {str(e)}")

    result_list = [
        {
            "id": key or uuid.uuid4().hex[:8],
            "title": title or (f"Zotero Item {key}" if key else "Zotero Item"),
            "url": f"zotero://select/items/{key}" if key else "",
        }
        for key, title in hits
    ]
    return json.dumps({"results": result_list}, separators=(",", ":"))

def find_related_papers(
    identifier: str,
    direction: Literal["references", "citations", "both"] = "both",
    limit: int | str | None = 20,
    *,
    ctx: Context,
) -> str:
    """Find references and/or citing works for a paper via OpenAlex."""
    try:
        if direction not in {"references", "citations", "both"}:
            return "Error: direction must be 'references', 'citations', or 'both'."

        limit = _helpers._normalize_limit(limit, default=20, max_val=50)
        backend = _library.get_library_backend()

        ctx.info(f"Resolving identifier to DOI: {identifier}")
        doi = _resolve_doi(identifier, backend)
        if not doi:
            return (
                f"Could not resolve a DOI for '{identifier}'. Provide a valid "
                "DOI / DOI-URL, or an 8-char Zotero item key whose item has a "
                "DOI in its metadata."
            )

        ctx.info(f"Querying OpenAlex for DOI {doi}")
        work = _openalex_get(f"{_OPENALEX_BASE}/works/https://doi.org/{doi}")
        if not work:
            return f"OpenAlex has no record for DOI '{doi}', or the lookup failed."

        want_refs = direction in {"references", "both"}
        want_cites = direction in {"citations", "both"}

        references: list[dict] = []
        citations: list[dict] = []
        # A failed lookup must not read as "none found" (#458).
        refs_incomplete = cites_failed = False

        if want_refs:
            ref_ids = [_short_id(r) for r in (work.get("referenced_works") or [])]
            ref_ids = [r for r in ref_ids if r]
            # A referenced work can be missing from OpenAlex; keep taking the
            # next ones until `limit` resolve, in referenced_works order.
            start = 0
            while start < len(ref_ids) and len(references) < limit:
                chunk = ref_ids[start:start + limit]
                start += len(chunk)
                data = _openalex_get(
                    f"{_OPENALEX_BASE}/works",
                    {"filter": "openalex_id:" + "|".join(chunk), "per-page": len(chunk)},
                )
                if data is None:
                    refs_incomplete = True
                    break
                by_id = {_short_id(w.get("id")): w for w in data.get("results") or []}
                references.extend(_work_summary(by_id[rid]) for rid in chunk if rid in by_id)
            references = references[:limit]

        if want_cites:
            cited_by_url = work.get("cited_by_api_url")
            # Sort server-side: sorting one unsorted page misses the most-cited works.
            cite_params: dict = {"per-page": min(limit, 50), "sort": "cited_by_count:desc"}
            if not cited_by_url:
                # OpenAlex no longer returns `cited_by_api_url` on work records, so the
                # citing works have to be queried through the `cites:` filter instead.
                work_id = _short_id(work.get("id"))
                if work_id:
                    cited_by_url = f"{_OPENALEX_BASE}/works"
                    cite_params["filter"] = f"cites:{work_id}"
            data = _openalex_get(cited_by_url, cite_params) if cited_by_url else None
            if data is None:
                cites_failed = True
            else:
                citations = [_work_summary(w) for w in data.get("results") or []]
                citations.sort(key=lambda p: p["cited_by"], reverse=True)
                citations = citations[:limit]

        # Flag library membership for every related paper.
        for p in references + citations:
            p["in_library"] = _doi_in_library(backend, p["doi"]) if p["doi"] else False

        src_title = work.get("title") or work.get("display_name") or doi
        output = [
            f"# Related Papers for: {src_title}",
            "",
            f"Source DOI: {doi}",
        ]
        summary_bits = []
        if want_refs:
            summary_bits.append(f"{len(references)} references" + (
                " (INCOMPLETE: an OpenAlex lookup failed)" if refs_incomplete else ""))
        if want_cites:
            summary_bits.append("citations lookup FAILED (this is not a zero)"
                                if cites_failed else f"{len(citations)} citations")
        in_lib = sum(1 for p in references + citations if p.get("in_library"))
        summary_bits.append(f"{in_lib} already in library")
        output.append("Found " + ", ".join(summary_bits) + ".")
        output.append("")

        if want_refs:
            output.extend(_render_related(references, "References (works this paper cites)"))
        if want_cites:
            output.extend(_render_related(citations, "Citations (works citing this paper)"))

        return "\n".join(output)

    except Exception as e:
        ctx.error(f"Error finding related papers: {e}")
        return f"Error finding related papers: {e}"

def set_item_parent(
    item_key: str,
    parent_key: str | None,
    *,
    ctx: Context,
) -> str:
    """Set ``parentItem`` through Zotero's versioned item-update API."""
    try:
        _read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        item = write_zot.item(item_key)
        payload = {
            "key": item["key"],
            "version": item["version"],
            "parentItem": parent_key if parent_key is not None else False,
        }
        response = write_zot.update_item(payload)
        if not _helpers._handle_write_response(response, ctx):
            return f"Failed to set parent for item '{item_key}'."

        if parent_key is None:
            return f"Successfully cleared the parent of item `{item_key}`."
        return f"Successfully set the parent of item `{item_key}` to `{parent_key}`."
    except Exception as e:
        ctx.error(f"Error setting parent for item {item_key}: {e}")
        return f"Error setting parent for item '{item_key}': {e}"

def authorize_local_writes(
    app_name: str = _client.DEFAULT_APP_NAME,
    timeout: int = 45,
    *,
    ctx: Context
) -> str:
    """Obtain a local API key, prompting the user in the Zotero app.

    Deliberately NOT wrapped in @with_zotero_api_lock, unlike every other
    write-adjacent tool here. This call blocks on a human decision; holding
    the shared API lock for that long would push every concurrent tool past
    its bounded acquire and turn one dialog into a wave of "Zotero is busy"
    errors. The narrower hazard — two dialogs at once — is covered by the
    dedicated lock inside client.authorize_local_api.
    """
    if not _utils.is_local_mode():
        return (
            "Local writes do not apply here: the server is not in local mode "
            "(ZOTERO_LOCAL is not set). Writes already go through the web API."
        )

    timeout = max(_MIN_TIMEOUT, min(_MAX_TIMEOUT, int(timeout)))

    try:
        ctx.info(f"Requesting local API authorization as {app_name!r}")
        result = _client.authorize_local_api(app_name=app_name, timeout=timeout)
    except _client.ZoteroAuthInProgressError as e:
        return f"Error: {e}"
    except LocalAPIDeniedError:
        return (
            "Authorization denied — the request was declined in Zotero. "
            "Call this tool again and choose \"Allow\" or \"Always Allow\"."
        )
    except TooManyRequestsError:
        return (
            "Zotero is rate-limiting authorization prompts (about 5 per "
            "minute). Wait a minute before trying again."
        )
    except UnsupportedParamsError:
        return (
            "This Zotero build does not expose the local write API, which "
            "needs Zotero 10 or newer. Set ZOTERO_API_KEY and "
            "ZOTERO_LIBRARY_ID to write through the web API instead."
        )
    except ParamNotPassedError:
        return "Error: app_name cannot be empty — it identifies this app in the dialog."
    # The local client is built from whichever HTTP library pyzotero uses
    # (httpx2 from 1.15), and the two libraries' exceptions are unrelated
    # classes, so catch both.
    except (httpx.TimeoutException, _client._pyzotero_httpx().TimeoutException):
        return (
            f"No answer within {timeout}s. The dialog is probably still open "
            "in Zotero — answer it there, then call this tool again. It will "
            "not open a second dialog while the first is pending."
        )
    except Exception as e:
        ctx.error(f"Local authorization failed: {e}")
        return f"Error requesting local API authorization: {e}"

    if result.get("remember"):
        return (
            "Local write access granted and saved.\n\n"
            "Writes now go straight to the running Zotero instead of the "
            "cloud. The key was stored in ~/.config/zotero-mcp/config.json "
            "and will be reused in future sessions. Revoke it with "
            "`zotero-mcp authorize-local --revoke`, or from Zotero's "
            "Settings > Advanced > Clear Write Authorizations."
        )
    return (
        "Local write access granted for a SINGLE write.\n\n"
        "\"Allow\" was chosen rather than \"Always Allow\", so this key is "
        "consumed by the next successful write and the one after that will "
        "fail. It has deliberately not been saved to disk, because a consumed "
        "key there would take priority over working web credentials on every "
        "later run. Ask the user to call this tool again and choose "
        "\"Always Allow\" for a key that persists."
    )

def write_capabilities(*, ctx: Context) -> str:
    """Describe the currently available write path."""
    caps = _client.get_write_capabilities()

    modes = {
        "local": "Local API — writes go directly to the running Zotero.",
        "hybrid": "Hybrid — local reads, writes through the Zotero web API.",
        "web": "Web API — reads and writes both go through zotero.org.",
        "none": "None — writes are not possible with the current configuration.",
    }
    lines = [
        "# Zotero write capabilities",
        "",
        f"**Mode:** {caps['mode']} — {modes[caps['mode']]}",
        "",
        f"- Local mode (ZOTERO_LOCAL): {'yes' if caps['local_mode'] else 'no'}",
    ]

    if caps["local_mode"]:
        supported = caps["server_supports_local_writes"]
        lines.append(
            f"- Running Zotero supports local writes: "
            f"{'yes' if supported else 'no (needs Zotero 10 or newer)'}"
        )
        if caps["has_local_key"]:
            remember = caps["local_key_remember"]
            validity = {
                True: "reusable",
                False: "SINGLE USE — consumed by the next write",
                None: "validity unknown",
            }[remember]
            lines.append(
                f"- Local API key: held, from {caps['local_key_source']} ({validity})"
            )
        else:
            lines.append("- Local API key: none")
        if not caps["local_write_enabled"]:
            lines.append("- Local writes are switched off by ZOTERO_LOCAL_WRITE")

    lines.append(
        f"- Web API credentials: {'set' if caps['has_web_credentials'] else 'not set'}"
    )

    if caps["mode"] == "none":
        lines += ["", "**To enable writes:**"]
        if caps["server_supports_local_writes"]:
            lines += [
                "1. Call zotero_authorize_local_writes and have the user "
                "choose \"Always Allow\" in Zotero.",
                "2. Or set ZOTERO_API_KEY and ZOTERO_LIBRARY_ID for web API writes.",
            ]
        else:
            lines.append(
                "- Set ZOTERO_API_KEY and ZOTERO_LIBRARY_ID for web API writes "
                "(this Zotero has no local write API)."
            )
    elif caps["mode"] == "hybrid" and caps["server_supports_local_writes"]:
        lines += [
            "",
            "This Zotero supports local writes. Calling "
            "zotero_authorize_local_writes would keep writes off the cloud "
            "round-trip.",
        ]

    return "\n".join(lines)

def get_attachment_path(
    item_key: str,
    *,
    ctx: Context
) -> str:
    """List resolved local paths for an item's attachments."""
    if not _utils.is_local_mode():
        return (
            "Error: zotero_get_attachment_path requires local mode "
            "(set ZOTERO_LOCAL=true). Cloud-only attachments have no local path."
        )
    try:
        from zotero_mcp.local_db import LocalZoteroReader

        with LocalZoteroReader(db_path=load_config().resolve_zotero_db_path()) as reader:
            attachments = reader.get_attachment_paths(item_key)
            if not attachments:
                # item_key may be the attachment's OWN key (get_item_by_key
                # excludes attachments, so the parent lookup yields nothing).
                att = reader.get_attachment_by_key(item_key)
                if att:
                    resolved = reader._resolve_attachment_path(att["key"], att.get("zotero_path") or "")
                    attachments = [{**att, "resolved_path": resolved,
                                    "exists": bool(resolved and resolved.exists())}]

        if not attachments:
            return f"No attachments found for item `{item_key}`."

        lines = [f"# Attachments for `{item_key}`", ""]
        for att in attachments:
            lines.append(f"## `{att['key']}` ({att['content_type'] or 'unknown'})")
            lines.append(f"- Zotero path: `{att['zotero_path']}`")
            if att["resolved_path"] is not None:
                marker = "" if att["exists"] else " (missing on disk)"
                lines.append(f"- Local path: `{att['resolved_path']}`{marker}")
            else:
                lines.append("- Local path: *unresolved*")
            lines.append("")
        return "\n".join(lines).rstrip()
    except Exception as e:
        ctx.error(f"Error resolving attachment path: {e}")
        return f"Error resolving attachment path: {e}"

def get_item_children(
    item_key: list[str] | str,
    *,
    ctx: Context
) -> str:
    """
    Get all child items (attachments, notes) for one or more Zotero items.

    Args:
        item_key: One item key, a list of keys, or a JSON/comma-separated
            string of keys
        ctx: MCP context

    Returns:
        Markdown-formatted list of child items. A single key renders the
        detailed per-type breakdown; several keys render one compact
        section per parent.
    """
    try:
        backend = _library.get_library_backend()
        keys = _helpers._normalize_str_list_input(item_key, "item_key")

        if not keys:
            return "Error: No item keys provided."

        if len(keys) == 1:
            return _format_children_detailed(backend, keys[0], ctx)
        return _format_children_grouped(backend, keys, ctx)

    except ValueError as e:
        return f"Input error: {e}"
    except Exception as e:
        ctx.error(f"Error fetching item children: {str(e)}")
        return f"Error fetching item children: {str(e)}"

def get_item_related(
    item_key: str,
    *,
    ctx: Context
) -> str:
    """
    Get all related items for a specific Zotero item.

    Args:
        item_key: Zotero item key/ID
        ctx: MCP context

    Returns:
        Markdown-formatted list of related items
    """
    try:
        ctx.info(f"Fetching related items for {item_key}")
        backend = _library.get_library_backend()

        # Fetch the item
        item = backend.get_item(item_key)
        if item is None:
            return f"Error: Item '{item_key}' not found."

        data = item.get("data", {})
        item_title = data.get("title", "Untitled")
        relations = data.get("relations", {})

        if not isinstance(relations, dict) or not relations:
            return f"No related items found for: **{item_title}** (Key: `{item_key}`)"

        # Extract related item keys from URIs
        # Zotero uses URIs like: http://zotero.org/users/{library_id}/items/{item_key}
        # or http://zotero.org/groups/{group_id}/items/{item_key}

        related_keys = []
        seen_keys = set()
        for rel_type, rel_values in relations.items():
            if not isinstance(rel_values, list):
                rel_values = [rel_values]
            for uri in rel_values:
                if not isinstance(uri, str):
                    continue
                # Extract item key from URI
                match = re.search(r'/items/([A-Z0-9]{8})$', uri)
                if match:
                    key = match.group(1)
                    # Deduplicate: same key may appear with both users/ and groups/ prefix
                    dedup_id = (rel_type, key)
                    if dedup_id not in seen_keys:
                        seen_keys.add(dedup_id)
                        related_keys.append((rel_type, key, uri))

        if not related_keys:
            return f"No related items found for: **{item_title}** (Key: `{item_key}`)"

        # Fetch details for related items
        output = [f"# Related Items for: {item_title}", f"**Item Key:** `{item_key}`", ""]

        # Group by relation type
        by_type = {}
        for rel_type, key, uri in related_keys:
            if rel_type not in by_type:
                by_type[rel_type] = []
            by_type[rel_type].append((key, uri))

        # One batched lookup for every related key, rather than one call per
        # relation as this used to do.
        related_items = backend.get_items([key for _, key, _ in related_keys])

        for rel_type, items in by_type.items():
            output.append(f"## Relation Type: `{rel_type}`")
            output.append("")

            for rel_key, uri in items:
                try:
                    rel_item = related_items.get(rel_key)
                    if rel_item is None:
                        raise KeyError(f"item {rel_key} is not in this library")
                    rel_data = rel_item.get("data", {})
                    rel_title = rel_data.get("title", "Untitled")
                    rel_type_name = rel_data.get("itemType", "unknown")
                    rel_date = rel_data.get("date", "")
                    rel_creator = ""
                    if rel_data.get("creators"):
                        first_creator = rel_data["creators"][0]
                        if "lastName" in first_creator:
                            rel_creator = first_creator["lastName"]
                        elif "name" in first_creator:
                            rel_creator = first_creator["name"]

                    creator_info = f", {rel_creator}" if rel_creator else ""
                    date_info = f" ({rel_date})" if rel_date else ""

                    output.append(f"- `{rel_key}` — **{rel_title}**{creator_info}{date_info}")
                    output.append(f"  - Type: {rel_type_name}")
                    if doi := rel_data.get("DOI"):
                        output.append(f"  - DOI: {doi}")
                    output.append("")
                except Exception as e:
                    output.append(f"- `{rel_key}` — (Could not fetch details: {e})")
                    output.append("")

        return "\n".join(output)

    except Exception as e:
        ctx.error(f"Error fetching related items: {str(e)}")
        return f"Error fetching related items: {str(e)}"

def enrich_search(
    query: str,
    limit: int | str = 10,
    *,
    ctx: Context,
) -> str:
    """Search Zotero and enrich results with Scite tallies."""
    try:
        if not query.strip():
            return "Error: search query cannot be empty"

        zot = _client.get_zotero_client()
        limit_int = _helpers._normalize_limit(limit, default=10)

        ctx.info(f"Searching Zotero for '{query}' and enriching with Scite data")
        zot.add_parameters(
            q=query,
            qmode="titleCreatorYear",
            itemType="-attachment",
            limit=limit_int,
        )
        results = zot.items()

        if not results:
            return f"No items found matching query: '{query}'"

        # Batch-enrich with Scite
        enrichment = enrich_items(results)

        output = [f"# Search Results for '{query}' (Scite-enriched)", ""]

        for i, item in enumerate(results, 1):
            doi = _extract_doi(item)
            extra = enrichment.get(doi, {}) if doi else {}
            output.extend(
                _utils.format_item_result(item, index=i, extra_fields=extra)
            )

        items_with_scite = sum(
            1 for item in results if _extract_doi(item) in enrichment
        )
        output.append(
            f"---\n*Scite data shown for {items_with_scite}/{len(results)} items "
            f"— powered by [scite.ai](https://scite.ai).*"
        )

        return "\n".join(output)

    except Exception as e:
        ctx.error(f"Error in enriched search: {e}")
        return f"Error in enriched search: {e}"

def check_retractions(
    collection: str | None = None,
    tag: str | None = None,
    limit: int | str = 50,
    *,
    ctx: Context,
) -> str:
    """Check Zotero items for editorial notices (retractions, corrections)."""
    try:
        zot = _client.get_zotero_client()
        limit_int = _helpers._normalize_limit(limit, default=50, max_val=500)

        # Fetch items
        if collection:
            ctx.info(f"Checking collection '{collection}' for retractions")
            keys = _helpers._resolve_collection_names(zot, [collection], ctx)
            if not keys:
                return f"Collection '{collection}' not found"
            items = zot.collection_items(
                keys[0], limit=limit_int, itemType="-attachment"
            )
        elif tag:
            ctx.info(f"Checking items tagged '{tag}' for retractions")
            zot.add_parameters(tag=tag, itemType="-attachment", limit=limit_int)
            items = zot.items()
        else:
            ctx.info("Checking recent items for retractions")
            items = zot.items(
                sort="dateModified",
                direction="desc",
                limit=limit_int,
                itemType="-attachment",
            )

        if not items:
            return "No items found to check."

        # Extract DOIs
        doi_items: dict[str, dict] = {}
        for item in items:
            doi = _extract_doi(item)
            if doi:
                doi_items[doi] = item

        if not doi_items:
            return f"None of the {len(items)} items have DOIs — cannot check Scite."

        ctx.info(f"Checking {len(doi_items)} DOIs against Scite editorial notices")
        papers = _scite.get_papers_batch(list(doi_items.keys()))

        if not papers:
            return "Could not reach Scite API — try again later."

        # Scite lowercases DOI keys in its responses; index by lowercase so
        # original-case DOIs (DOIs are case-insensitive) still match.
        papers = {k.lower(): v for k, v in papers.items()}

        # Find items with notices
        flagged: list[tuple[dict, list[dict]]] = []
        for doi, item in doi_items.items():
            paper = papers.get(doi.lower(), {})
            notices = paper.get("editorialNotices", [])
            if notices:
                flagged.append((item, notices))

        if not flagged:
            return (
                f"All clear! Checked {len(doi_items)} items with DOIs — "
                "no retractions or editorial notices found."
            )

        output = [
            "# Editorial Notice Alerts",
            f"Found **{len(flagged)}** item(s) with editorial notices "
            f"(out of {len(doi_items)} checked):",
            "",
        ]

        for i, (item, notices) in enumerate(flagged, 1):
            data = item.get("data", {})
            title = data.get("title", "Untitled")
            item_doi = data.get("DOI", "")
            output.append(f"## {i}. {title}")
            output.append(f"**DOI:** {item_doi}")
            for notice in notices:
                # Scite's /papers notices are {status, date, noticeDoi, doi};
                # older {type, sourceDoi} shapes kept as fallbacks.
                ntype = (
                    notice.get("status")
                    or notice.get("type")
                    or notice.get("editorialNoticeType")
                    or "notice"
                )
                ntype = ntype.replace("_", " ").title()
                ndate = notice.get("date", "")
                source = (
                    notice.get("noticeDoi")
                    or notice.get("sourceDoi")
                    or notice.get("source")
                    or ""
                )
                link = f"https://doi.org/{source}" if source else "(no notice DOI)"
                output.append(f"- **{ntype}**{f' ({ndate})' if ndate else ''}: {link}")
            output.append("")

        output.append(
            "---\n*Powered by [scite.ai](https://scite.ai).*"
        )

        return "\n".join(output)

    except Exception as e:
        ctx.error(f"Error checking retractions: {e}")
        return f"Error checking retractions: {e}"

def synthesize_annotations(
    collection_key: str | None = None,
    tag: list[str] | str | None = None,
    limit: int | str | None = 200,
    format: Literal["markdown", "json"] = "markdown",
    *,
    ctx: Context,
) -> str:
    """Gather annotations and notes into a per-paper digest for synthesis.

    Args:
        collection_key: Optional collection to restrict the digest to.
        tag: Optional tag filter (string, JSON list, or list).
        limit: Maximum annotations/notes to scan.
        format: ``markdown`` for a readable digest or ``json`` for structured
            per-paper annotation and note records.
        ctx: MCP context.

    Returns:
        Markdown digest or a JSON object containing summary counts and papers.
    """
    try:
        ctx.info("Gathering annotations and notes for synthesis")
        backend = _library.get_library_backend()

        limit = _helpers._normalize_limit(limit, default=200, max_val=5000)
        tags = _helpers._normalize_tag_filter(tag)

        # Determine the set of allowed paper keys if a collection is scoped.
        allowed_keys: set[str] | None = None
        if collection_key:
            try:
                coll_items = backend.collection_items(collection_key) or []
                allowed_keys = {
                    key for it in coll_items
                    if it.get("data", {}).get("itemType") != "attachment"
                    and (key := it.get("key"))
                }
            except Exception as e:
                ctx.warning(f"Could not load collection items: {e}")
                allowed_keys = set()

        try:
            annotations = backend.list_items("annotation", limit=limit, tag=tags)
        except Exception as e:
            ctx.warning(f"Annotation fetch failed: {e}")
            annotations = []
        try:
            notes = backend.list_items("note", limit=limit, tag=tags)
        except Exception as e:
            ctx.warning(f"Note fetch failed: {e}")
            notes = []

        if not annotations and not notes:
            if format == "json":
                return json.dumps({
                    "summary": {"papers": 0, "highlights": 0, "notes": 0},
                    "papers": [],
                }, indent=2)
            scope = f" in collection {collection_key}" if collection_key else ""
            return f"No annotations or notes found{scope}."

        # Group by resolved paper key so same-title papers stay distinct.
        context_cache: dict[str, dict[str, str | None]] = {}
        papers: dict[str, dict] = {}

        def _bucket(context: dict[str, str | None]) -> dict:
            item_key = context.get("item_key")
            title = context.get("parent_title") or "(unknown source)"
            bucket_key = item_key or title
            return papers.setdefault(bucket_key, {
                "item_key": item_key,
                "title": title,
                "highlights": [],
                "notes": [],
            })

        def _in_scope(parent_key: str) -> bool:
            if allowed_keys is None:
                return True
            # Member if the immediate parent, or its grandparent paper, is in scope.
            if parent_key in allowed_keys:
                return True
            parent = backend.get_item(parent_key)
            data = parent.get("data", {}) if parent else {}
            gp = data.get("parentItem")
            return bool(gp and gp in allowed_keys)

        highlight_count = 0
        for anno in annotations:
            data = anno.get("data", {})
            parent_key = data.get("parentItem")
            text = (data.get("annotationText") or "").strip()
            comment = (data.get("annotationComment") or "").strip()
            if not text and not comment:
                continue
            if parent_key and not _in_scope(parent_key):
                continue
            context = (
                _resolve_paper_context(backend, parent_key, context_cache)
                if parent_key
                else {
                    "item_key": None,
                    "attachment_key": None,
                    "parent_title": "(unknown source)",
                    "attachment_title": None,
                }
            )
            record = _annotation_to_record(anno, context)
            # Preserve this tool's existing whitespace-trimming behaviour.
            record["text"] = text
            record["comment"] = comment
            _bucket(context)["highlights"].append(record)
            highlight_count += 1

        note_count = 0
        for note in notes:
            data = note.get("data", {})
            parent_key = data.get("parentItem")
            raw = data.get("note") or ""
            text = _utils.clean_html(raw).strip()
            if not text:
                continue
            if parent_key and not _in_scope(parent_key):
                continue
            context = (
                _resolve_paper_context(backend, parent_key, context_cache)
                if parent_key
                else {
                    "item_key": None,
                    "attachment_key": None,
                    "parent_title": "(standalone note)",
                    "attachment_title": None,
                }
            )
            if len(text) > 400:
                text = text[:400] + "..."
            _bucket(context)["notes"].append({
                "note_key": note.get("key") or None,
                "item_key": context.get("item_key"),
                "parent_title": context.get("parent_title"),
                "text": text,
                "tags": [
                    item["tag"]
                    for item in _helpers._normalize_item_tags(data.get("tags"))
                ],
                "created": data.get("dateAdded") or None,
                "modified": data.get("dateModified") or None,
            })
            note_count += 1

        if not papers:
            if format == "json":
                return json.dumps({
                    "summary": {"papers": 0, "highlights": 0, "notes": 0},
                    "papers": [],
                }, indent=2)
            scope = f" in collection {collection_key}" if collection_key else ""
            return f"No annotations or notes found{scope}."

        sorted_papers = sorted(papers.values(), key=lambda paper: paper["title"])
        if format == "json":
            return json.dumps({
                "summary": {
                    "papers": len(papers),
                    "highlights": highlight_count,
                    "notes": note_count,
                },
                "papers": sorted_papers,
            }, ensure_ascii=False, indent=2)

        output = [
            "# Annotation & Note Digest",
            "",
            (f"**{len(papers)} papers, {highlight_count} highlights, {note_count} notes**"),
            "",
        ]

        # Buckets are keyed by item key, so two distinct papers can share a
        # title — qualify the heading with the key when that happens.
        title_counts = Counter(paper["title"] for paper in sorted_papers)
        for bucket in sorted_papers:
            heading = bucket["title"]
            if title_counts[heading] > 1 and bucket["item_key"]:
                heading = f"{heading} ({bucket['item_key']})"
            output.append(f"## {heading}")
            if bucket["highlights"]:
                output.append("**Highlights:**")
                for highlight in bucket["highlights"]:
                    text = highlight["text"]
                    comment = highlight["comment"]
                    line = f"- {text}" if text else "- (comment only)"
                    if comment:
                        line += f" — *{comment}*"
                    output.append(line)
            if bucket["notes"]:
                output.append("**Notes:**")
                for note in bucket["notes"]:
                    output.append(f"- {note['text']}")
            output.append("")

        output.append(
            "*You can now synthesize themes, agreements, and contradictions across these papers from the digest above.*"
        )

        result = "\n".join(output)
        return _helpers._prepend_size_warning(
            result,
            "Scope to a collection_key or narrow with tag to reduce size.",
        )

    except Exception as e:
        ctx.error(f"Error synthesizing annotations: {str(e)}")
        return f"Error synthesizing annotations: {str(e)}"

def batch_update(
    item_keys: list[str] | str | None = None,
    query: str = "",
    tag: str | list[str] | None = None,
    add_tags: list[str] | str | None = None,
    remove_tags: list[str] | str | None = None,
    set_keys: dict[str, str] | str | None = None,
    remove_keys: list[str] | str | None = None,
    limit: int | str = 50,
    *,
    ctx: Context
) -> str:
    """Batch tag and Extra-field edits over one item selection.

    A thin facade: the selection is shared, then the tag edits and the
    Extra-field edits run through their own (unchanged) implementations
    and their reports are concatenated.
    """
    has_selector = bool(item_keys) or bool(query) or bool(tag)
    tag_action = bool(add_tags) or bool(remove_tags)
    extra_action = bool(set_keys) or bool(remove_keys)

    if not has_selector:
        return (
            "Error: Must provide at least one selector — item_keys, "
            "query, and/or tag."
        )
    if not tag_action and not extra_action:
        return (
            "Error: Must provide at least one action — add_tags, "
            "remove_tags, set_keys, and/or remove_keys."
        )

    reports = []
    if tag_action:
        reports.append(batch_update_tags(
            query=query, add_tags=add_tags, remove_tags=remove_tags,
            tag=tag, limit=limit, item_keys=item_keys, ctx=ctx,
        ))
    if extra_action:
        reports.append(batch_update_extra(
            item_keys=item_keys, set_keys=set_keys, remove_keys=remove_keys,
            query=query, tag=tag, limit=limit, ctx=ctx,
        ))
    return "\n\n".join(reports)

def create_collection(
    name: str,
    parent_collection: str | None = None,
    *,
    ctx: Context
) -> str:
    try:
        read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        ctx.info(f"Creating collection '{name}'")

        # Resolve parent_collection name if it doesn't look like a key
        parent_key = parent_collection
        if parent_collection and not re.match(r'^[A-Z0-9]{8}$', parent_collection):
            try:
                keys = _helpers._resolve_collection_names(read_zot, [parent_collection], ctx=ctx)
                parent_key = keys[0] if keys else None
            except ValueError as e:
                return f"Error resolving parent collection: {_helpers.format_zotero_error(e)}"

        coll_data = {"name": name}
        if parent_key:
            coll_data["parentCollection"] = parent_key
        else:
            coll_data["parentCollection"] = False

        result = write_zot.create_collections([coll_data])

        if isinstance(result, dict) and result.get("success"):
            coll_key = next(iter(result["success"].values()))
            parent_info = f" under parent '{parent_collection}'" if parent_collection else ""
            return (
                f"Successfully created collection \"{name}\"{parent_info}\n\n"
                f"Collection key: `{coll_key}`"
            )
        return f"Failed to create collection: {result}"

    except Exception as e:
        ctx.error(f"Error creating collection: {e}")
        return f"Error creating collection: {_helpers.format_zotero_error(e)}"

def delete_collection(
    collection_key: str,
    *,
    ctx: Context
) -> str:
    try:
        _read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        ctx.info(f"Deleting collection {collection_key}")

        try:
            coll = write_zot.collection(collection_key)
        except Exception as e:
            return f"Collection not found: `{collection_key}` ({e})"

        name = coll.get("data", {}).get("name", collection_key)
        resp = write_zot.delete_collection(coll)
        if _helpers._handle_write_response(resp, ctx):
            return f"Deleted collection \"{name}\" (`{collection_key}`)"
        return f"Failed to delete collection `{collection_key}`: {resp}"

    except Exception as e:
        ctx.error(f"Error deleting collection: {e}")
        return f"Error deleting collection: {_helpers.format_zotero_error(e)}"

def update_collection(
    collection_key: str,
    name: str | None = None,
    parent_collection: str | None = None,
    to_top_level: bool = False,
    *,
    ctx: Context
) -> str:
    try:
        read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        if name is not None and not name.strip():
            return "Error: name cannot be empty."
        if parent_collection and to_top_level:
            return "Error: pass parent_collection or to_top_level=True, not both."
        if name is None and not parent_collection and not to_top_level:
            return "Error: nothing to change. Pass name, parent_collection or to_top_level=True."

        try:
            coll = write_zot.collection(collection_key)
        except Exception as e:
            return f"Collection not found: `{collection_key}` ({_helpers.format_zotero_error(e)})"

        data = dict(coll.get("data", {}))
        data.setdefault("key", coll.get("key", collection_key))
        if "version" not in data and "version" in coll:
            data["version"] = coll["version"]
        old_name = data.get("name", collection_key)
        changes = []

        if name is not None and name != old_name:
            data["name"] = name
            changes.append(f"renamed to \"{name}\"")

        if parent_collection:
            parent_key = parent_collection
            if not re.match(r"^[A-Z0-9]{8}$", parent_collection):
                try:
                    keys = _helpers._resolve_collection_names(read_zot, [parent_collection], ctx=ctx)
                except ValueError as e:
                    return f"Error resolving parent collection: {_helpers.format_zotero_error(e)}"
                parent_key = keys[0] if keys else None
                if not parent_key:
                    return f"Error: parent collection not found: {parent_collection}"
            # Zotero accepts a parent that is the collection itself or one of
            # its descendants and the tree then disappears from the desktop
            # client, so refuse the cycle here.
            own_subtree = set(_helpers.expand_collection_scope(read_zot, collection_key, True))
            own_subtree.add(collection_key)
            if parent_key in own_subtree:
                return (
                    f"Error: cannot move `{collection_key}` under `{parent_key}`, "
                    "which is the collection itself or one of its subcollections."
                )
            if data.get("parentCollection") != parent_key:
                data["parentCollection"] = parent_key
                changes.append(f"moved under `{parent_key}`")
        elif to_top_level and data.get("parentCollection"):
            data["parentCollection"] = False
            changes.append("moved to the top level")

        if not changes:
            return f"No change: collection \"{old_name}\" (`{collection_key}`) already matches."

        resp = write_zot.update_collection(data)
        if _helpers._handle_write_response(resp, ctx):
            return f"Updated collection \"{old_name}\" (`{collection_key}`): " + "; ".join(changes)
        return f"Failed to update collection `{collection_key}`: {resp}"

    except Exception as e:
        ctx.error(f"Error updating collection: {e}")
        return f"Error updating collection: {_helpers.format_zotero_error(e)}"

def search_collections(
    query: str,
    include_trashed: bool = False,
    *,
    ctx: Context
) -> str:
    try:
        backend = _library.get_library_backend()
        ctx.info(f"Searching collections for '{query}'")

        collections = backend.list_collections(include_trashed=include_trashed)
        trashed_keys = {
            c["key"] for c in collections
            if c.get("key") and c.get("data", {}).get("deleted")
        }
        if not collections:
            return "No collections found in your Zotero library."

        words = query.lower().split()
        matching = [
            c for c in collections
            if all(w in c.get("data", {}).get("name", "").lower() for w in words)
        ]

        if not matching:
            return f"No collections found matching '{query}'"

        # The whole listing is already here, so a parent's name is a dict
        # lookup rather than one API call per matching collection.
        names_by_key = {
            c["key"]: c.get("data", {}).get("name", "")
            for c in collections if c.get("key")
        }

        lines = [f"# Collections matching '{query}'", ""]
        for i, coll in enumerate(matching, 1):
            name = coll["data"].get("name", "Unnamed")
            key = coll["key"]
            parent_key = coll["data"].get("parentCollection")
            trash_marker = " *[trashed]*" if key in trashed_keys else ""
            lines.append(f"## {i}. {name}{trash_marker}")
            lines.append(f"**Key:** `{key}`")
            if parent_key:
                parent = names_by_key.get(parent_key)
                if parent:
                    lines.append(f"**Parent:** {parent}")
                else:
                    lines.append(f"**Parent key:** {parent_key}")
            lines.append("")

        return "\n".join(lines)

    except Exception as e:
        ctx.error(f"Error searching collections: {e}")
        return f"Error searching collections: {_helpers.format_zotero_error(e)}"

def manage_collections(
    item_keys: list[str] | str,
    add_to: list[str] | str | None = None,
    remove_from: list[str] | str | None = None,
    *,
    ctx: Context
) -> str:
    try:
        read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        keys = _helpers._normalize_str_list_input(item_keys, "item_keys")
        add_specs = _helpers._normalize_str_list_input(add_to, "add_to")
        remove_specs = _helpers._normalize_str_list_input(remove_from, "remove_from")

        if not keys:
            return "Error: No item keys provided."
        if not add_specs and not remove_specs:
            return "Error: Must specify add_to and/or remove_from."

        # Resolve specs (keys, names, or '/'-paths) to live collection keys
        # before doing any work. Resolution also validates existence — Zotero
        # will happily accept add/remove against a trashed collection, leaving
        # items parented under an invisible bucket so the caller sees
        # "success" but nothing renders in the desktop client (#233).
        try:
            add_colls = _helpers.resolve_collection_specs(
                read_zot, add_specs, ctx=ctx
            )
            remove_colls = _helpers.resolve_collection_specs(
                read_zot, remove_specs, ctx=ctx
            )
        except ValueError as e:
            return f"Error: {e}"

        results = []

        # Cache item fetches to avoid repeated API calls for the same key
        item_cache = {}
        def _get_item(key):
            if key not in item_cache:
                item_cache[key] = write_zot.item(key)
            return item_cache[key]

        for coll_key in add_colls:
            for item_key in keys:
                item_dict = _get_item(item_key)
                resp = write_zot.addto_collection(coll_key, item_dict)
                if _helpers._handle_write_response(resp, ctx):
                    results.append(f"Added {item_key} to {coll_key}")
                    # Invalidate cache — version changed after addto_collection
                    item_cache.pop(item_key, None)
                else:
                    results.append(f"Failed to add {item_key} to {coll_key}")

        for coll_key in remove_colls:
            for item_key in keys:
                item_dict = _get_item(item_key)
                resp = write_zot.deletefrom_collection(coll_key, item_dict)
                if _helpers._handle_write_response(resp, ctx):
                    results.append(f"Removed {item_key} from {coll_key}")
                    item_cache.pop(item_key, None)
                else:
                    results.append(f"Failed to remove {item_key} from {coll_key}")

        return "\n".join(results)

    except ValueError as e:
        return f"Input error: {e}"
    except Exception as e:
        ctx.error(f"Error managing collections: {e}")
        return f"Error managing collections: {_helpers.format_zotero_error(e)}"

def delete_item(
    item_key: str,
    allow_note: bool = False,
    *,
    ctx: Context
) -> str:
    """
    Move a Zotero item to the Trash.

    Args:
        item_key: Zotero item key/ID to trash
        allow_note: If True, permits trashing note items. Default False
            directs callers to zotero_manage_note(action='delete') for
            notes (same mechanism, explicit about what it affects).
        ctx: MCP context

    Returns:
        Confirmation message, or an error if the item cannot be trashed.
    """
    try:
        _, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        ctx.info(f"Trashing item {item_key}")

        try:
            item = write_zot.item(item_key)
        except Exception:
            return f"Error: No item found with key: {item_key}"

        data = item.get("data", {})
        item_type = data.get("itemType", "unknown")

        if item_type == "note" and not allow_note:
            return (
                f"Error: Item {item_key} is a note. Use "
                "zotero_manage_note(action='delete') for notes, or pass "
                "allow_note=True to override."
            )

        # pyzotero's delete_item() permanently destroys items, and update_item()
        # strips the "deleted" field, so trashing is a direct PATCH with
        # {"deleted": 1} — recoverable by the user.
        ok, detail = _helpers.trash_item(write_zot, item)
        if ok:
            return (
                f"Successfully trashed item {item_key} "
                f"(type={item_type}, recoverable from Zotero's Trash)"
            )
        return f"Failed to trash item {item_key}: {detail}"

    except Exception as e:
        ctx.error(f"Error trashing item: {str(e)}")
        return f"Error trashing item: {_helpers.format_zotero_error(e)}"

def merge_duplicates(
    keeper_key: str | None = None,
    duplicate_keys: list[str] | str | None = None,
    confirm: bool = False,
    auto: bool = False,
    method: Literal["title", "doi", "both"] = "doi",
    collection_key: str | None = None,
    max_groups: int | str | None = None,
    plan_token: str | None = None,
    *,
    ctx: Context
) -> str:
    try:
        read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        if auto:
            if keeper_key or duplicate_keys:
                return (
                    "Error: auto=True finds and picks its own groups — do not "
                    "pass keeper_key or duplicate_keys with it. Drop auto=True "
                    "to merge one specific group."
                )
            return _merge_duplicates_auto(
                read_zot, write_zot, method, collection_key,
                max_groups, confirm, plan_token, ctx,
            )

        if not keeper_key:
            return (
                "Error: keeper_key is required. Pass keeper_key + "
                "duplicate_keys to merge one group, or auto=True to merge "
                "every high-confidence group."
            )

        dup_keys = _helpers._normalize_str_list_input(duplicate_keys, "duplicate_keys")

        # Safety: remove keeper from duplicates
        if keeper_key in dup_keys:
            dup_keys.remove(keeper_key)
            ctx.warning(f"Keeper key '{keeper_key}' was in duplicate list — removed.")

        if not dup_keys:
            return "Error: No duplicate keys to merge (after removing keeper if present)."

        plan = _merge_plan(write_zot, keeper_key, dup_keys)

        if not confirm:
            skipped = plan["skipped_attachment_count"]
            lines = [
                "# Merge Preview (dry run)",
                "",
                f"**Keeper:** `{keeper_key}` — {plan['keeper'].get('data', {}).get('title', 'Untitled')}",
                f"**Duplicates to merge:** {', '.join(f'`{k}`' for k in dup_keys)}",
                "",
                f"**Tags to add:** {sorted(plan['new_tags']) if plan['new_tags'] else 'none'}",
                f"**Collections to add:** {sorted(plan['new_collections']) if plan['new_collections'] else 'none'}",
                f"**Child items to re-parent:** {plan['children_to_move']}",
                f"  ({skipped} duplicate attachment(s) will be skipped)" if skipped
                else "  (notes, PDFs, annotations, highlights, etc.)",
                "",
                "Duplicates will be moved to **Trash** (recoverable in Zotero).",
                "",
                "**Call again with `confirm=True` to execute.**",
            ]
            return "\n".join(lines)

        ctx.info(f"Merging {len(dup_keys)} duplicates into {keeper_key}")
        result = _execute_merge(write_zot, plan, ctx)
        if result["error"]:
            return f"Merge partially completed. {result['error']}\n\nFix the failures and retry."

        skip_info = (
            f" ({len(result['skipped_dupes'])} duplicate attachments skipped)"
            if result["skipped_dupes"] else ""
        )
        return (
            f"Merge complete.\n\n"
            f"- Tags merged: {len(result['new_tags'])} new\n"
            f"- Collections added: {len(result['new_collections'])} new\n"
            f"- Children re-parented: {len(result['moved'])}{skip_info}\n"
            f"- Duplicates trashed: {', '.join(f'`{k}`' for k in result['trashed'])}\n\n"
            "Trashed items can be restored from Zotero's Trash."
        )

    except ValueError as e:
        return f"Input error: {e}"
    except Exception as e:
        ctx.error(f"Error merging duplicates: {e}")
        return f"Error merging duplicates: {_helpers.format_zotero_error(e)}"

def get_pdf_outline(
    item_key: str,
    *,
    ctx: Context
) -> str:
    # NOT decorated with @with_zotero_api_lock: the lock exists only to
    # serialize Zotero API access, and holding it across the outline
    # extraction meant one slow or hung PDF blocked every other tool in the
    # server until the client gave up (#431). It is taken below around the
    # API work alone and released before the extraction subprocess runs.
    try:
        ctx.info(f"Getting PDF outline for item {item_key}")

        with tempfile.TemporaryDirectory() as tmpdir:
            with zotero_api_lock():
                backend = _library.get_library_backend()

                attachment_key = None
                filename = "document.pdf"

                # The key may name the PDF attachment itself — attachments have
                # no children, so the parent scan below would find nothing (#372).
                item = backend.get_item(item_key)
                data = item.get("data", {}) if isinstance(item, dict) else {}
                if (
                    data.get("itemType") == "attachment"
                    and data.get("contentType") == "application/pdf"
                ):
                    attachment_key = item.get("key") or data.get("key") or item_key
                    filename = data.get("filename") or f"{attachment_key}.pdf"
                else:
                    for child in backend.get_children([item_key]).get(item_key, []):
                        child_data = child.get("data", {})
                        if child_data.get("contentType") == "application/pdf":
                            attachment_key = child["key"]
                            filename = child_data.get("filename") or "document.pdf"
                            break

                if not attachment_key:
                    return f"No PDF attachment found for item `{item_key}`."

                # The multi-source downloader reads a file already in Zotero's
                # own storage in place (the only option with Zotero closed) and
                # otherwise fetches it, so WebDAV- and cloud-backed attachments
                # still work. The outline is only read, never modified.
                zot = _client.get_zotero_client()
                local_mode = _utils.is_local_mode()
                download = _client.download_attachment_file(
                    attachment_key,
                    tmpdir,
                    os.path.basename(filename),
                    local_client=(
                        zot if local_mode else _client.get_local_zotero_client()
                    ),
                    web_client=None if local_mode else zot,
                    in_place=True,
                )
                pdf_path = download.path
                download_errors = download.errors
                if (
                    not pdf_path
                    or not pdf_path.exists()
                    or pdf_path.stat().st_size == 0
                ):
                    detail = (
                        f" ({'; '.join(download_errors)})" if download_errors else ""
                    )
                    return (
                        f"Could not download PDF for attachment "
                        f"`{attachment_key}`.{detail}"
                    )

            # Lock released: parsing a file we already have on disk needs no
            # Zotero API access, and it is the slow part.
            outcome = _extract_pdf_toc(str(pdf_path))

        if outcome.status == "no_pymupdf":
            return (
                "Error: PyMuPDF (fitz) is required for PDF outline extraction. "
                f"{_utils.install_hint('pdf')}"
            )
        if outcome.status == "crashed":
            return (
                f"Could not read the outline of attachment `{attachment_key}`: "
                f"the PDF reader crashed on this file ({outcome.detail}). The "
                "crash was contained in a separate process, so the server is "
                "unaffected. Try zotero_read_pdf_pages or "
                "zotero_get_item_fulltext for this item instead."
            )
        if outcome.status == "timeout":
            return (
                f"Timed out reading the outline of attachment "
                f"`{attachment_key}` ({outcome.detail})."
            )
        if outcome.status != "ok":
            return (
                f"Error extracting PDF outline for attachment "
                f"`{attachment_key}`: {outcome.detail}"
            )

        if not outcome.toc:
            return "This PDF does not contain a table of contents/outline."

        lines = [f"# PDF Outline for item `{item_key}`", ""]
        for level, title, page in outcome.toc:
            indent = "  " * (level - 1)
            lines.append(f"{indent}- {title} (p. {page})")

        return "\n".join(lines)

    except ZoteroApiBusyError:
        # Same as every lock-decorated tool: surface "busy" to the caller
        # rather than reporting it as a PDF failure.
        raise
    except Exception as e:
        ctx.error(f"Error extracting PDF outline: {e}")
        return f"Error extracting PDF outline: {_helpers.format_zotero_error(e)}"

def attach_file(
    item_key: str,
    file_path: str | None = None,
    url: str | None = None,
    filename: str | None = None,
    *,
    ctx: Context,
) -> str:
    try:
        _read_zot, write_zot = _helpers._get_write_client(ctx)
    except ValueError as e:
        return str(e)

    try:
        if bool(file_path) == bool(url):
            return "Error: Provide exactly one of file_path or url."

        # Validate the parent item before touching any file.
        try:
            item = write_zot.item(item_key)
        except Exception as e:
            return f"Error: Item '{item_key}' not found ({e})."
        item_data = item.get("data", {}) or {}
        item_type = item_data.get("itemType")
        if item_type in ("attachment", "note", "annotation"):
            parent = item_data.get("parentItem")
            hint = f" Use its parent item key '{parent}' instead." if parent else ""
            return (
                f"Error: '{item_key}' has itemType '{item_type}', not a "
                f"regular item — attachments must go on the parent item.{hint}"
            )

        if filename:
            # Strip any path components from a caller-supplied name.
            filename = os.path.basename(filename.strip())

        if file_path:
            # Path validation — check symlink BEFORE resolving
            if os.path.islink(file_path):
                return "Error: Symlinks are not allowed for security reasons."
            if not os.path.isabs(file_path):
                return "Error: file_path must be an absolute path."
            file_path = os.path.realpath(file_path)
            if not os.path.isfile(file_path):
                return f"Error: File not found: {file_path}"
            ext = os.path.splitext(file_path)[1].lower()
            if ext not in _ATTACH_ALLOWED_EXTS:
                return (
                    f"Error: Unsupported file type '{ext}'. "
                    f"Allowed: {', '.join(sorted(_ATTACH_ALLOWED_EXTS))}"
                )
            if filename and not filename.lower().endswith(ext):
                # Mirror the URL branch's .pdf enforcement: an override
                # without the source's extension would strip it from the
                # stored file (and break the MIME-type guess).
                filename += ext
            display_name = filename or os.path.basename(file_path)
            ctx.info(f"Attaching local file to {item_key}: {display_name}")
            if filename and filename != os.path.basename(file_path):
                # pyzotero's attachment_both() derives the *stored* filename
                # from the real file's basename, not the title tuple element
                # — stage the file under the override name in a scratch dir
                # so the override actually controls what gets stored (and so
                # the dedupe check in _upload_attachment, which compares
                # against stored filenames, converges on re-run).
                with tempfile.TemporaryDirectory() as tmpdir:
                    staged_path = os.path.join(tmpdir, filename)
                    shutil.copy2(file_path, staged_path)
                    # Must run inside the with-block — temp file disappears on exit.
                    return _upload_attachment(
                        write_zot, item_key, display_name, staged_path, ctx
                    )
            return _upload_attachment(write_zot, item_key, display_name, file_path, ctx)

        return _attach_from_url(write_zot, item_key, url, filename, ctx)

    except Exception as e:
        ctx.error(f"Error attaching file: {e}")
        return f"Error attaching file: {e}"

def add_item(
    source: str,
    source_type: Literal[
        "auto", "doi", "url", "isbn", "bibtex", "csl_json", "file"
    ] = "auto",
    collections: list[str] | str | None = None,
    tags: list[str] | str | None = None,
    attach_mode: str = "auto",
    if_exists: Literal["duplicate", "file", "skip"] = "duplicate",
    create_missing_collections: bool = False,
    title: str | None = None,
    *,
    ctx: Context
) -> str:
    """Detect the shape of ``source`` and dispatch to the matching adder."""
    # Tolerate structured CSL JSON arriving as a real object/array rather
    # than a string — clients do this when the user pastes JSON. An empty
    # container is "nothing supplied", not an empty JSON document.
    if source is not None and not isinstance(source, str):
        if isinstance(source, (list, dict)) and not source:
            source = ""
        else:
            try:
                source = json.dumps(source)
            except (TypeError, ValueError):
                return "Error: source must be a string."

    resolved = (source_type or "auto").strip().lower()
    if resolved in ("", "auto"):
        try:
            resolved = detect_source_type(source)
        except ValueError as e:
            return f"Error: {e}"
        ctx.info(f"Detected source_type='{resolved}'")
    elif resolved not in _ADD_SOURCE_TYPES:
        return (
            f"Error: source_type must be 'auto' or one of "
            f"{_ADD_SOURCE_TYPES}."
        )

    source = source.strip() if isinstance(source, str) else source

    common = {
        "collections": collections,
        "tags": tags,
        "if_exists": if_exists,
        "create_missing_collections": create_missing_collections,
        "ctx": ctx,
    }

    if resolved == "doi":
        return add_by_doi(doi=source, attach_mode=attach_mode, **common)
    if resolved == "url":
        return add_by_url(url=source, attach_mode=attach_mode, **common)
    if resolved == "isbn":
        return add_by_isbn(isbn=source, **common)
    if resolved == "file":
        return add_from_file(file_path=source, title=title, **common)
    # BibTeX / CSL JSON arrive either inline or as a path to a citation file.
    if resolved == "bibtex":
        if _is_citation_path(source, _BIBTEX_EXTS):
            return add_by_bibtex(file_path=source, attach_mode=attach_mode, **common)
        return add_by_bibtex(bibtex=source, attach_mode=attach_mode, **common)
    if _is_citation_path(source, _CSL_JSON_EXTS):
        return add_by_csl_json(file_path=source, attach_mode=attach_mode, **common)
    return add_by_csl_json(csl_json=source, attach_mode=attach_mode, **common)
